/* ===== Sitio público: inicio, catálogo, ficha, sala, resultado, blog, venta, ayuda y legales ===== */
const photo=m=>m?.url||'assets/propiedades/propiedad-16.webp';
const occupancyNote=o=>o==='Ocupada'?'Ocupada según lo informado':o==='Desocupada'?'Desocupada según lo informado':'Ocupación por confirmar';

/* ---------- tarjeta de propiedad: tasación, oferta vigente, crédito y cierre visibles sin abrir la ficha ---------- */
/* Descuento respecto de la tasación, sobre la oferta vigente (o el precio inicial si aún no hay ofertas). */
const discount=(p,a)=>{const cur=a?a.currentMinor/100:p.conditions?.initialUF;return p.appraisalUF&&cur?Math.round((1-cur/p.appraisalUF)*100):0};
/* Tarjeta: datos fijos (comuna, m², dormitorios, baños, tasación, crédito, me gusta) y casillas según el estado:
   abierta → oferta vigente, n° de ofertas, oferta mínima y cierre (la cuenta regresiva reemplaza la etiqueta "En vivo"); próxima → precio inicial y fecha;
   cerrada → top 2 de ofertas con fecha y hora, n° de ofertas, inicio y cierre. */
const shortDate=t=>t?new Intl.DateTimeFormat('es-CL',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',hour12:false,timeZone:TZ}).format(new Date(t)):'—';
const stat=(label,value,live)=>h`<div><dt>${label}</dt><dd ${live?raw(`data-live="${live}"`):''}>${value}</dd></div>`;
function cardState(p,a,s){
 if(s==='scheduled'){const t=a?.start??p.conditions?.opensAt;const part=o=>t?new Intl.DateTimeFormat('es-CL',{...o,timeZone:TZ}).format(new Date(t)):'—';
  return h`<div class="card-start"><div class="start-cal" aria-hidden="true"><span>${part({month:'short'}).replace('.','')}</span><strong>${part({day:'numeric'})}</strong></div><div class="start-info"><small>Comienza</small><strong>${part({weekday:'long',day:'numeric',month:'long'})}</strong><span>${part({hour:'2-digit',minute:'2-digit',hour12:false})} hrs · hora de Chile</span></div></div>
  <dl class="card-stats" data-kind="scheduled"><div class="wide"><dt>Precio inicial</dt><dd>${a?money(a.initialMinor/100):money(p.conditions?.initialUF)}</dd></div></dl>`}
 if(s==='closed'||s==='cancelled')return h`<div class="card-closed">${a?.top?.length?h`<ol class="top-bids" aria-label="Las 2 ofertas más altas">${a.top.map(b=>h`<li><strong>${money(b.amountMinor/100)}</strong><time datetime="${new Date(b.time).toISOString()}">${shortDate(b.time)}</time></li>`)}</ol>`:h`<p class="hint">Sin ofertas registradas.</p>`}
  <dl class="card-stats three" data-kind="closed">${stat('Ofertas',a?.totalBids||0)}${stat('Inicio',shortDate(a?.start))}${stat('Cierre',shortDate(a?.end))}</dl></div>`;
 return h`<div class="card-live"><div class="card-live-main"><div><small>Oferta vigente</small><strong data-live="current-open">${money(a?.totalBids?a.currentMinor/100:0)}</strong></div><div class="n"><small>N° de ofertas</small><strong data-live="bids">${a?.totalBids||0}</strong></div></div>
  <dl class="card-stats" data-kind="open">${stat('Oferta mínima',a?money(a.nextMinor/100):'—','next')}${stat('Cierre',shortDate(a?.end))}</dl></div>`}
function propertyCard(p){const a=p.auction&&Live.get(p.auctionId)||p.auction;const s=Live.status(a);const saved=state.saved.has(p.id);const off=discount(p,a);const room='/remates/'+p.slug;
 const fact=(ic,txt,label)=>txt==null?'':h`<li title="${label}">${icon(ic)}<span>${txt}</span><span class="visually-hidden"> ${label}</span></li>`;
 const photoTag=h`<img class="property-image" src="${photo(p.media?.[0])}" alt="${p.media?.[0]?.alt||'Imagen de la propiedad'}" loading="lazy" width="640" height="426">`;
 // Cerrada o cancelada: la tarjeta queda de fondo, apagada, y encima solo el resumen (top 2, n° de ofertas, inicio y cierre).
 if(s==='closed'||s==='cancelled')return h`<article class="property-card is-closed" data-live-id="${p.auctionId}" aria-label="${p.title}: ${STATUS_LABEL[s].toLowerCase()}">
  <div class="closed-bg" aria-hidden="true"><div class="image-wrap">${photoTag}<span class="status-pill" data-state="${s}">${STATUS_LABEL[s]}</span>${off>0?h`<span class="discount-badge"><strong>${off}%</strong><small>Bajo tasación</small></span>`:''}</div>
   <div class="property-body"><h3 class="property-title">${p.title}</h3><ul class="card-facts">${fact('pin',p.commune,'comuna')}${fact('area',p.area?`${p.area} m²`:null,'superficie')}${fact('bed',p.rooms!=null?p.rooms:null,'dormitorios')}${fact('bath',p.baths!=null?p.baths:null,'baños')}</ul><div class="card-meta">${p.appraisalUF?h`<span>Tasación <strong>${money(p.appraisalUF)}</strong></span>`:''}</div></div></div>
  <div class="closed-panel"><p class="closed-head">${icon('lock')}<strong>${s==='cancelled'?'Oportunidad cancelada':'Oportunidad cerrada'}</strong></p>
   ${a?.top?.length?h`<ol class="top-bids" aria-label="Las 2 ofertas más altas">${a.top.map(b=>h`<li><strong>${money(b.amountMinor/100)}</strong><time datetime="${new Date(b.time).toISOString()}">${shortDate(b.time)}</time></li>`)}</ol>`:h`<p class="hint">Sin ofertas registradas.</p>`}
   <dl class="card-stats three" data-kind="closed">${stat('Ofertas',a?.totalBids||0)}${stat('Inicio',shortDate(a?.start))}${stat('Cierre',shortDate(a?.end))}</dl></div></article>`;
 // Suspendida: tarjeta bloqueada, solo con el aviso y su motivo.
 if(s==='paused')return h`<article class="property-card is-blocked" data-live-id="${p.auctionId}" aria-disabled="true"><div class="image-wrap">${photoTag}<span class="status-pill" data-live="status" data-state="${s}">${STATUS_LABEL[s]}</span></div>
  <div class="property-body"><h3 class="property-title">${p.title}</h3><div class="suspended-note" role="note">${icon('lock')}<div><strong>Oportunidad suspendida</strong><p>${a?.pauseReason||'La recepción de ofertas está detenida.'}</p></div></div></div></article>`;
 return h`<article class="property-card" data-live-id="${p.auctionId}" data-appraisal="${p.appraisalUF||''}">
 <div class="image-wrap"><a href="${href(room)}" tabindex="-1" aria-hidden="true">${photoTag}</a>${s==='open'?h`<span class="status-pill timer" data-state="open" title="Tiempo para el cierre"><span data-live="countdown">${Live.countdown(a)}</span></span>`:h`<span class="status-pill" data-live="status" data-state="${s}">${STATUS_LABEL[s]}</span>`}
  <button class="save-btn ${saved?'saved':''}" data-action="save" data-id="${p.id}" data-public="${p.publicId}" aria-pressed="${saved}" aria-label="${saved?'Quitar me gusta':'Me gusta'}: ${p.title}">${icon('heart')}</button>
  ${off>0?h`<span class="discount-badge" aria-hidden="true"><strong data-live="discount">${off}%</strong><small>Bajo tasación</small></span>`:''}</div>
 <div class="property-body"><h3 class="property-title"><a href="${href(room)}">${p.title}</a></h3>
  <ul class="card-facts">${fact('pin',p.commune,'comuna')}${fact('area',p.area?`${p.area} m²`:null,'superficie')}${fact('bed',p.rooms!=null?p.rooms:null,p.rooms===1?'dormitorio':'dormitorios')}${fact('bath',p.baths!=null?p.baths:null,p.baths===1?'baño':'baños')}</ul>
  <div class="card-meta">${p.appraisalUF?h`<span>Tasación <strong>${money(p.appraisalUF)}</strong></span>`:''}${p.mortgage?h`<span class="mortgage-flag" title="Admite crédito hipotecario">${icon('bank')}Con crédito</span>`:''}</div>
  ${cardState(p,a,s)}
  <div class="card-actions"><a class="btn btn-outline" href="${href(room)}#bases">Ver documentos</a><a class="btn btn-dark" href="${href(s==='closed'||s==='cancelled'?room+'/resultado':room)}">Ver estado</a><a class="btn btn-primary" href="${href('/contacto?tema=compra-inmediata&propiedad='+p.publicId)}">Compra inmediata</a></div></div></article>`}
actions.save=async el=>{const id=Number(el.dataset.id);if(!state.user){toast('Inicia sesión para guardar propiedades.');return navigate('/ingresar?volver='+encodeURIComponent(currentUrl().pathname+currentUrl().search))}const on=!state.saved.has(id);try{if(on)await POST(`/api/v1/properties/${id}/save`);else await DEL(`/api/v1/properties/${id}/save`);on?state.saved.add(id):state.saved.delete(id);$$(`[data-action="save"][data-id="${id}"]`).forEach(b=>{b.classList.toggle('saved',on);b.setAttribute('aria-pressed',String(on));if(b.dataset.text!==undefined)b.textContent=on?'Quitar de guardadas':'Guardar propiedad'});toast(on?'Propiedad guardada.':'Propiedad quitada de guardadas.','success');if(on)Analytics.event('property_saved',{property_id:el.dataset.public})}catch(e){toast(e.message,'error')}};
actions.share=async el=>{const url=location.origin+(FILE_MODE?location.pathname+location.hash:currentUrl().pathname);const title=el.dataset.title||document.title;try{if(navigator.share){await navigator.share({title,url});Analytics.event('share',{method:'native',content_type:el.dataset.kind||'page'})}else{await navigator.clipboard.writeText(url);toast('Enlace copiado.','success');Analytics.event('share',{method:'copy',content_type:el.dataset.kind||'page'})}}catch{}};

/* ---------- buscador con sugerencias (combobox accesible) ---------- */
function searchBox({value='',id='heroSearch',label='Comuna, región o tipo de propiedad'}={}){return h`<form class="search-box" role="search" data-form="search" data-nodraft><label class="visually-hidden" for="${id}">${label}</label><input id="${id}" name="q" type="search" value="${value}" placeholder="${label}" autocomplete="off" role="combobox" aria-expanded="false" aria-controls="${id}-list" aria-autocomplete="list" data-nodraft><button type="submit">${icon('search')}<span>Buscar</span></button><ul class="suggestions" id="${id}-list" role="listbox" hidden></ul></form>`}
forms.search=form=>{const q=form.q.value.trim();Analytics.event('search_submitted',{search_term:q});navigate('/remates'+(q?'?q='+encodeURIComponent(q):''))};
let suggestTimer;
document.addEventListener('input',e=>{const input=e.target.closest('.search-box input[role=combobox]');if(!input)return;clearTimeout(suggestTimer);suggestTimer=setTimeout(async()=>{const list=$('#'+input.getAttribute('aria-controls'));const q=input.value.trim();if(q.length<2){list.hidden=true;input.setAttribute('aria-expanded','false');return}try{const {items}=await GET('/api/v1/properties/suggest?q='+encodeURIComponent(q));list.innerHTML=toHtml(items.map((s,i)=>h`<li role="option" id="${list.id}-${i}" data-value="${s.label}"><span>${s.label}</span><small>${s.kind}</small></li>`));list.hidden=!items.length;input.setAttribute('aria-expanded',String(!!items.length))}catch{list.hidden=true}},180)});
document.addEventListener('keydown',e=>{const input=e.target.closest('.search-box input[role=combobox]');if(!input)return;const list=$('#'+input.getAttribute('aria-controls'));const opts=$$('[role=option]',list);if(list.hidden||!opts.length)return;let i=opts.findIndex(o=>o.getAttribute('aria-selected')==='true');if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();i=e.key==='ArrowDown'?(i+1)%opts.length:(i-1+opts.length)%opts.length;opts.forEach((o,k)=>o.setAttribute('aria-selected',String(k===i)));input.setAttribute('aria-activedescendant',opts[i].id)}else if(e.key==='Enter'&&i>=0){e.preventDefault();input.value=opts[i].dataset.value;list.hidden=true;input.form.requestSubmit()}else if(e.key==='Escape'){list.hidden=true;input.setAttribute('aria-expanded','false')}});
document.addEventListener('click',e=>{const o=e.target.closest('.suggestions [role=option]');if(o){const input=o.closest('.search-box').querySelector('input');input.value=o.dataset.value;o.parentElement.hidden=true;input.form.requestSubmit()}else $$('.suggestions').forEach(l=>{if(!l.parentElement.contains(e.target))l.hidden=true})});

/* ---------- PUB-01 Inicio de Remates ---------- */
route('/',{title:'Inicio',view:async()=>{const c=state.config;const [list,blog]=await Promise.all([GET('/api/v1/properties?limit=60'),GET('/api/v1/blog/posts?limit=3').catch(()=>({items:[]}))]);
 const featured=(c.featured||[]).map(id=>list.items.find(p=>p.id===id)).filter(Boolean);const st=p=>Live.status(p.auction);const byFeatured=[...featured,...list.items.filter(p=>!featured.includes(p))];
 // Destacados: subastas abiertas y cerradas (primero las elegidas en Gestión). Próximas: por fecha de inicio.
 const shown=byFeatured.filter(p=>['open','closed'].includes(st(p))).sort((a,b)=>(st(a)==='closed')-(st(b)==='closed')||(b.auction?.end||0)-(a.auction?.end||0)).slice(0,8);
 const upcoming=list.items.filter(p=>st(p)==='scheduled').sort((a,b)=>(a.auction?.start||0)-(b.auction?.start||0)).slice(0,8);const [main,...rest]=blog.items;
 Analytics.event('view_home',{});
 return {title:'Oportunidades inmobiliarias',html:h`<section class="hero"><div class="hero-text"><span class="eyebrow on-dark">Oportunidades inmobiliarias</span><h1>${brandTitle(c.homeTitle)}</h1><p>${c.homeLead}</p></div>${homeSearch()}</section>
 ${upcoming.length?h`<section class="section catalog-teaser" aria-labelledby="nextTitle"><div class="section-head"><div><span class="eyebrow">Próximas oportunidades</span><h2 id="nextTitle">Prepárate antes de que abran</h2><p>Revisa la ficha, los documentos y la fecha de inicio de cada oportunidad.</p></div><a class="text-link" href="${href('/remates?status=scheduled')}">Ver todas ${icon('arrow')}</a></div>${carousel(upcoming,'nextTitle')}</section>`:''}
 <section class="section catalog-teaser" aria-labelledby="featTitle"><div class="section-head"><div><span class="eyebrow">Oportunidades destacadas</span><h2 id="featTitle">Propiedades con descuento real</h2><p>Compara la tasación, revisa las ofertas y participa con crédito hipotecario. <small class="hint">Datos ilustrativos.</small></p></div><a class="text-link" href="${href('/remates')}">Ver todos ${icon('arrow')}</a></div>${shown.length?carousel(shown,'featTitle'):h`<div class="empty-state"><p>No hay oportunidades destacadas por ahora.</p><a class="btn btn-dark" href="${href('/remates')}">Ver catálogo</a></div>`}${moneyNote()}</section>
 ${main?h`<section class="section blog-section" aria-labelledby="blogTitle"><div class="section-head"><div><span class="eyebrow">Información para decidir</span><h2 id="blogTitle">Noticias y guías para comprar y vender</h2><p>Contenido editorial para entender cada etapa.</p></div><a class="text-link" href="${href('/blog')}">Ver todas las noticias ${icon('arrow')}</a></div>
  <div class="blog-home"><a class="blog-feature" href="${href('/blog/'+main.slug)}"><img src="${main.cover.url}" alt="${main.cover.alt}" loading="lazy"><div class="blog-feature-content"><span class="blog-tag">${main.category?.name||'Blog'}</span><h3>${main.title}</h3><p>${main.excerpt}</p><span class="btn btn-light btn-sm">Leer artículo</span></div></a><div class="blog-list">${rest.map(p=>h`<a class="blog-row" href="${href('/blog/'+p.slug)}"><img src="${p.cover.url}" alt="${p.cover.alt}" loading="lazy" width="120" height="80"><span><strong>${p.title}</strong><small>${p.category?.name||''} · ${p.readMinutes} min de lectura</small></span></a>`)}</div></div></section>`:''}
 <section class="section faq-section" aria-labelledby="faqTitle"><h2 id="faqTitle">Preguntas frecuentes</h2>${faqList(c.faqs.slice(0,4))}<a class="text-link" href="${href('/preguntas-frecuentes')}">Ver todas las preguntas ${icon('arrow')}</a></section>`}}});
/* Carrusel horizontal de tarjetas con botones anterior/siguiente (el desplazamiento táctil también funciona). */
const carousel=(items,labelId)=>h`<div class="carousel"><button type="button" class="carousel-btn prev" data-action="carousel" data-dir="-1" aria-label="Anteriores">${icon('back')}</button><div class="carousel-track" role="list" aria-labelledby="${labelId}">${items.map(p=>h`<div class="carousel-item" role="listitem">${propertyCard(p)}</div>`)}</div><button type="button" class="carousel-btn next" data-action="carousel" data-dir="1" aria-label="Siguientes">${icon('chevron')}</button></div>`;
actions.carousel=el=>{const t=el.parentElement.querySelector('.carousel-track');t.scrollBy({left:Number(el.dataset.dir)*t.clientWidth*.9,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})};
/* Buscador de inicio: Todas / Residencial / Comercial, comuna, puja mínima (en UF) y fecha de subasta. */
const MIN_BIDS=[1000,2000,3000,5000,8000];
function homeSearch(){const regions=window.__CHILE||{};
 return h`<form class="home-search" data-form="home-search" data-nodraft aria-label="Buscar propiedades"><fieldset class="seg-tabs"><legend class="visually-hidden">Tipo de propiedad</legend>${[['','Todas'],['residencial','Residencial'],['comercial','Comercial']].map(([v,l],i)=>h`<label><input type="radio" name="segment" value="${v}" ${i?'':'checked'}><span>${l}</span></label>`)}</fieldset>
 <div class="home-search-fields"><label class="form-field"><span>Comuna</span><select name="commune"><option value="">Todas</option>${Object.entries(regions).map(([r,list])=>h`<optgroup label="${r}">${list.map(c=>h`<option>${c}</option>`)}</optgroup>`)}</select></label>
 <label class="form-field"><span>Puja mínima</span><select name="min"><option value="">Cualquiera</option>${MIN_BIDS.map(v=>h`<option value="${v}">Desde ${money(v)}</option>`)}</select></label></div>
 <button class="btn btn-primary">${icon('search')} Buscar</button><a class="text-link" href="${href('/mi-cuenta/notificaciones')}">Recibir alertas inmobiliarias ${icon('chevron')}</a></form>`}
forms['home-search']=form=>{const d=formData(form);const params=new URLSearchParams();for(const k of ['segment','commune','min'])if(d[k])params.set(k,d[k]);if(d.min)params.set('unit','UF');Analytics.event('search_submitted',{search_term:[...params.values()].join(' ')});navigate('/remates'+(params.size?'?'+params:''))};
/* Titular según el manual: sin punto final; «|» separa la segunda idea (en Light) y *palabra* marca la palabra clave en lima. */
const brandTitle=t=>{const [a,b]=String(t||'').replace(/\.\s*$/,'').split('|');const kw=x=>esc(x).replace(/\*([^*]+)\*/,'<em>$1</em>').replace(/\*/g,'');return raw(kw(a)+(b?`<br><span class="light">${kw(b.trim())}</span>`:''))};
const faqList=items=>h`<div class="faq-list">${items.map(f=>h`<details><summary>${f.q}</summary><p>${f.a}</p></details>`)}</div>`;

/* ---------- PUB-02 Catálogo: filtros, orden, vistas lista/calendario/mapa, paginación por cursor ---------- */
const FILTER_KEYS=['q','segment','region','commune','type','min','max','unit','rooms','baths','area','occupancy','date','status'];
const STATUS_FILTERS=[['open','Abiertas'],['scheduled','Próximas'],['paused','Suspendidas'],['closed','Cerradas']];
function filterForm(q,f,{sheet=false}={}){const unit=q.unit||state.currency;const communes=q.region?(f.communes[q.region]||[]):Object.values(f.communes).flat().sort((a,b)=>a.localeCompare(b,'es'));const statuses=(q.status||'').split(',');
 return h`<form class="filter-panel" data-form="filters" data-nodraft aria-label="Filtros"><h2 class="${sheet?'visually-hidden':''}">Filtra tu búsqueda</h2>
 <label class="form-field"><span>Región</span><select name="region" data-action-change="region"><option value="">Todas</option>${f.regions.map(r=>h`<option ${q.region===r?'selected':''}>${r}</option>`)}</select></label>
 <label class="form-field"><span>Comuna</span><select name="commune"><option value="">Todas</option>${communes.map(c=>h`<option ${q.commune===c?'selected':''}>${c}</option>`)}</select></label>
 <label class="form-field"><span>Tipo de propiedad</span><select name="type"><option value="">Todos</option>${f.types.map(t=>h`<option ${q.type===t?'selected':''}>${t}</option>`)}</select></label>
 <fieldset class="form-field"><legend>Precio en ${unit} <small>(oferta vigente o precio inicial)</small></legend><input type="hidden" name="unit" value="${unit}"><div class="field-pair"><label><span class="visually-hidden">Mínimo</span><input name="min" type="number" inputmode="numeric" min="0" placeholder="Mínimo" value="${q.min||''}"></label><label><span class="visually-hidden">Máximo</span><input name="max" type="number" inputmode="numeric" min="0" placeholder="Máximo" value="${q.max||''}"></label></div>${unit==='CLP'&&!ufInfo().available?h`<small class="hint warn">No hay valor UF vigente: el filtro en pesos no se aplicará.</small>`:''}</fieldset>
 <div class="field-pair"><label class="form-field"><span>Dormitorios</span><select name="rooms"><option value="">Todos</option>${[1,2,3,4].map(n=>h`<option value="${n}" ${q.rooms==n?'selected':''}>${n}+</option>`)}</select></label><label class="form-field"><span>Baños</span><select name="baths"><option value="">Todos</option>${[1,2,3].map(n=>h`<option value="${n}" ${q.baths==n?'selected':''}>${n}+</option>`)}</select></label></div>
 <label class="form-field"><span>Superficie útil mínima (m²)</span><input name="area" type="number" inputmode="numeric" min="0" value="${q.area||''}"></label>
 <label class="form-field"><span>Ocupación</span><select name="occupancy"><option value="">Todas</option>${f.occupancy.map(o=>h`<option ${q.occupancy===o?'selected':''}>${o}</option>`)}</select></label>
 <fieldset class="form-field"><legend>Estado de la oportunidad</legend>${STATUS_FILTERS.map(([v,l])=>h`<label class="form-check"><input type="checkbox" name="st_${v}" ${statuses.includes(v)?'checked':''}> <span>${l}</span></label>`)}</fieldset>
 <input type="hidden" name="q" value="${q.q||''}"><div class="sheet-actions"><button type="button" class="btn btn-outline" data-action="clear-filters">Limpiar</button><button type="submit" class="btn btn-primary">Ver resultados</button></div></form>`}
document.addEventListener('change',e=>{const s=e.target.closest('form[data-form="filters"] select[name=region]');if(!s)return;const f=catalogState.facets;const commune=s.form.commune;const list=s.value?(f.communes[s.value]||[]):Object.values(f.communes).flat().sort((a,b)=>a.localeCompare(b,'es'));commune.innerHTML=toHtml(h`<option value="">Todas</option>${list.map(c=>h`<option>${c}</option>`)}`)});
const catalogState={facets:{regions:[],communes:{},types:[],occupancy:[]}};
forms.filters=form=>{const d=formData(form);const params={};for(const k of FILTER_KEYS)params[k]=d[k]||'';params.status=STATUS_FILTERS.map(([v])=>v).filter(v=>d['st_'+v]).join(',');params.n='';const used=Object.entries(params).filter(([k,v])=>v&&!['unit','q','n'].includes(k)).map(([k])=>k);form.closest('dialog')?.close();setQuery(params);Analytics.event('filters_applied',{filters:used.join(',')||'ninguno'});render({keepScroll:false})};
actions['clear-filters']=el=>{el.closest('dialog')?.close();const params={};FILTER_KEYS.forEach(k=>params[k]='');params.n='';setQuery(params);render()};
actions['remove-filter']=el=>{const k=el.dataset.key;if(k.startsWith('status:')){const s=currentUrl().searchParams.get('status').split(',').filter(x=>x!==k.slice(7)).join(',');setQuery({status:s,n:''})}else setQuery({[k]:'',...(k==='region'?{commune:''}:{}),n:''});render()};
actions['open-filters']=el=>{const u=currentUrl();openDialog({title:'Filtros',body:filterForm(Object.fromEntries(u.searchParams),catalogState.facets,{sheet:true}),wide:true,onOpen:d=>{d.classList.add('sheet');$('select,input:not([type=hidden])',d)?.focus()}})};
actions.sort=el=>{setQuery({sort:el.value,n:''});render({keepScroll:true})};
actions.view=el=>{setQuery({view:el.dataset.value});render({keepScroll:true})};
actions['load-more']=el=>{const n=Number(currentUrl().searchParams.get('n')||12)+12;setQuery({n});render({keepScroll:true})};
document.addEventListener('change',e=>{if(e.target.matches('select[data-action="sort"]'))actions.sort(e.target)});
route('/remates',{title:'Todas las propiedades',parent:'/',view:async({query})=>{const q=query;const n=Math.min(Number(q.n)||12,60);const params=new URLSearchParams();for(const k of [...FILTER_KEYS,'sort'])if(q[k])params.set(k,q[k]);params.set('limit',String(n));
 const view=q.view||'list';if(view!=='list')params.set('limit','60');
 let data;try{data=await GET('/api/v1/properties?'+params)}catch(e){if(e.status===0)return {title:'Todas las propiedades',html:h`<section class="subpage-head"><h1>Oportunidades inmobiliarias</h1></section><div class="empty-state error"><p>No pudimos cargar el catálogo.</p><button class="btn btn-dark" data-action="reload">Reintentar</button></div>`};throw e}
 catalogState.facets=data.facets;
 const labels={segment:'Propiedad',date:'Fecha de inicio',region:'Región',commune:'Comuna',type:'Tipo',min:'Desde',max:'Hasta',rooms:'Dorm.',baths:'Baños',area:'m² desde',occupancy:'Ocupación',q:'Búsqueda'};
 const chips=[...Object.keys(labels).filter(k=>q[k]).map(k=>({key:k,label:`${labels[k]}: ${['min','max'].includes(k)?(q.unit==='CLP'?fmt.clp(q[k]):fmt.uf(q[k])):['rooms','baths'].includes(k)?q[k]+'+':k==='segment'?(q[k]==='comercial'?'Comercial':'Residencial'):k==='date'?fmt.date(new Date(q[k]+'T12:00:00')):q[k]}`})),...(q.status?q.status.split(',').filter(Boolean).map(s=>({key:'status:'+s,label:STATUS_FILTERS.find(x=>x[0]===s)?.[1]||s})):[])];
 const results=view==='calendar'?calendarView(data.items):view==='map'?h`<div id="catalogMap" class="catalog-map" role="region" aria-label="Mapa con ubicaciones aproximadas"><p class="hint">Cargando mapa…</p></div><ul class="map-list">${data.items.map(p=>h`<li><a href="${href('/remates/'+p.slug)}">${p.title}</a> · ${p.publicLocation} · <span data-live-id="${p.auctionId}"><span data-live="status">${STATUS_LABEL[Live.status(p.auction)]}</span></span></li>`)}</ul>`:data.items.length?h`<div class="property-list">${data.items.map(propertyCard)}</div>${data.nextCursor?h`<div class="load-more"><button class="btn btn-outline" data-action="load-more">Cargar más propiedades</button><small>Mostrando ${data.items.length} de ${data.total}</small></div>`:''}`:'';
 return {title:'Oportunidades inmobiliarias',html:h`<section class="subpage-head"><nav class="breadcrumbs" aria-label="Migas de pan"><a href="${href('/')}">Inicio</a><span aria-hidden="true">›</span><span aria-current="page">Todas las propiedades</span></nav><h1>Oportunidades inmobiliarias</h1><p>Usa los filtros para encontrar por región, comuna, tipo, precio y más. Los valores se muestran en ${state.currency==='CLP'?'pesos (equivalencia referencial)':'UF'}.</p></section>
 <div class="catalog-layout"><aside class="catalog-filters desktop-only">${filterForm(q,data.facets)}</aside><section class="catalog-results" aria-labelledby="resCount">
  <div class="catalog-tools"><p id="resCount" class="results-count" aria-live="polite"><strong>${data.total}</strong> ${data.total===1?'propiedad encontrada':'propiedades encontradas'}</p><button class="btn btn-outline btn-sm mobile-only" data-action="open-filters">${icon('filter')} Filtros${chips.length?` (${chips.length})`:''}</button>
   <label class="sort"><span>Ordenar</span><select data-action="sort" aria-label="Ordenar resultados">${[['closing','Cierre más próximo'],['start','Inicio más próximo'],['recent','Publicación más reciente'],['price_asc','Menor precio'],['price_desc','Mayor precio']].map(([v,l])=>h`<option value="${v}" ${(q.sort||'closing')===v?'selected':''}>${l}</option>`)}</select></label>
   <div class="view-toggle" role="group" aria-label="Presentación">${[['list','Lista','list'],['calendar','Calendario','calendar'],['map','Mapa','map']].map(([v,l,i])=>h`<button class="chip ${view===v?'active':''}" data-action="view" data-value="${v}" aria-pressed="${view===v}">${icon(i)} ${l}</button>`)}</div></div>
  ${chips.length?h`<div class="active-chips" aria-label="Filtros activos">${chips.map(c=>h`<button class="chip removable" data-action="remove-filter" data-key="${c.key}" aria-label="Quitar filtro ${c.label}">${c.label} ${icon('close')}</button>`)}<button class="text-link" data-action="clear-filters">Limpiar todo</button></div>`:''}
  ${data.priceFilterUnavailable?h`<p class="notice warn">El filtro de precio en pesos no se aplicó porque no hay un valor UF vigente.</p>`:''}
  ${data.items.length?results:h`<div class="empty-state"><h2>No encontramos propiedades con estos filtros</h2><p>Prueba quitando algún filtro o escríbenos para avisarte cuando haya opciones.</p><div class="button-row center"><button class="btn btn-dark" data-action="clear-filters">Limpiar filtros</button><a class="btn btn-outline" href="${href('/contacto')}">Contactar al equipo</a></div></div>`}${moneyNote()}</section></div>`,
  after:()=>{if(view==='map')mountMap($('#catalogMap'),data.items)}}}});
function calendarView(items){const rows=items.filter(p=>p.auction).map(p=>({p,a:Live.get(p.auctionId)||p.auction})).sort((x,y)=>(Live.status(x.a)==='scheduled'?x.a.start:x.a.end)-(Live.status(y.a)==='scheduled'?y.a.start:y.a.end));const groups=new Map();for(const r of rows){const t=Live.status(r.a)==='scheduled'?r.a.start:r.a.end;const k=fmt.monthLabel(t);(groups.get(k)||groups.set(k,[]).get(k)).push({...r,t})}
 return h`<div class="calendar">${[...groups].map(([month,list])=>h`<section><h2 class="calendar-month">${month}</h2><ol>${list.map(({p,a,t})=>h`<li class="calendar-item" data-live-id="${p.auctionId}"><time datetime="${new Date(t).toISOString()}"><strong>${new Intl.DateTimeFormat('es-CL',{day:'2-digit',timeZone:TZ}).format(new Date(t))}</strong><small>${new Intl.DateTimeFormat('es-CL',{weekday:'short',timeZone:TZ}).format(new Date(t))}</small></time><div><span class="status-pill" data-live="status" data-state="${Live.status(a)}">${STATUS_LABEL[Live.status(a)]}</span><a href="${href('/remates/'+p.slug)}"><strong>${p.title}</strong></a><small>${p.publicLocation} · Empieza ${fmt.short(a.start)} · Termina ${fmt.short(a.end)} (hora de Chile)</small><small data-live="countdown">${Live.countdown(a)}</small></div></li>`)}</ol></section>`)}</div>`}
/* Mapa con coordenadas aproximadas (comuna); se carga solo al elegir la vista. */
let leafletLoading=null;function loadLeaflet(){if(window.L)return Promise.resolve();if(leafletLoading)return leafletLoading;leafletLoading=new Promise((res,rej)=>{const css=document.createElement('link');css.rel='stylesheet';css.href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';document.head.append(css);const s=document.createElement('script');s.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';s.onload=res;s.onerror=rej;document.head.append(s)});return leafletLoading}
/* Mapas con Leaflet y teselas de OpenStreetMap (atribución siempre visible). */
const OSM_TILES='https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',OSM_ATTRIBUTION='© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors';
function pointMap(el,{lat,lng},{popup='',zoom=16}={}){const map=L.map(el,{scrollWheelZoom:false});L.tileLayer(OSM_TILES,{maxZoom:19,attribution:OSM_ATTRIBUTION}).addTo(map);const m=L.marker([lat,lng],{keyboard:true,title:popup||'Ubicación'}).addTo(map);if(popup)m.bindPopup(esc(popup));map.setView([lat,lng],zoom);setTimeout(()=>map.invalidateSize(),60);return map}
async function mountMap(el,items,{zoom}={}){if(!el)return;const pts=items.filter(p=>p.lat!=null&&p.lng!=null);if(!pts.length){el.innerHTML='<p class="hint">No hay ubicaciones aproximadas aprobadas para mostrar.</p>';return}try{await loadLeaflet();el.innerHTML='';const map=L.map(el,{scrollWheelZoom:false});L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:15,attribution:OSM_ATTRIBUTION}).addTo(map);const b=[];for(const p of pts){const ll=[p.lat,p.lng];b.push(ll);L.circle(ll,{radius:900,color:'#3A2A86',fillColor:'#C6FF34',fillOpacity:.45,weight:2}).addTo(map).bindPopup(`<strong>${esc(p.title)}</strong><br>${esc(p.publicLocation)}<br><a href="${href('/remates/'+p.slug)}">Ver ficha</a>`)}if(b.length===1)map.setView(b[0],zoom||13);else map.fitBounds(b,{padding:[30,30]})}catch{el.innerHTML='<p class="hint">No se pudo cargar el mapa. Las ubicaciones son aproximadas por comuna; revisa la lista.</p>'}}

/* ---------- PUB-03 Ficha de propiedad ---------- */
route('/remates/:slug',{title:'Ficha',parent:'/remates',sticky:true,view:async({params})=>{const {property:p,related,result}=await GET('/api/v1/properties/'+encodeURIComponent(params.slug));if(p.auction)Live.accept({auctions:[p.auction]});const a=Live.get(p.auctionId);const s=Live.status(a);
 Analytics.event('property_viewed',{property_id:p.publicId,property_type:p.type,commune:p.commune,auction_status:s});const saved=state.saved.has(p.id);
 const essentials=[['Tipo',p.type],['Ubicación autorizada',p.publicLocation],['Superficie útil',p.area?`${p.area} m²`:null],['Superficie de terreno',p.plot?`${p.plot} m²`:null],['Dormitorios',p.rooms],['Baños',p.baths],['Estacionamientos',p.parking],['Ocupación informada',p.occupancy],['Gastos comunes',p.expenses?fmt.clp(p.expenses):'No informado'],['ID público',p.publicId]].filter(([,v])=>v!=null&&v!=='');
 return {title:p.title,html:h`<div class="detail-layout" data-live-id="${p.auctionId}"><div class="detail-main">
  <nav class="breadcrumbs" aria-label="Migas de pan"><a href="${href('/')}">Inicio</a><span aria-hidden="true">›</span><a href="${href('/remates')}">Propiedades</a><span aria-hidden="true">›</span><a href="${href('/remates?commune='+encodeURIComponent(p.commune))}">${p.commune}</a><span aria-hidden="true">›</span><span aria-current="page">${p.type}</span></nav>
  <header class="detail-head"><div><span class="status-pill" data-live="status" data-state="${s}">${STATUS_LABEL[s]}</span><h1>${p.title}</h1><p class="detail-location">${icon('pin')} ${p.publicLocation} · ubicación aproximada</p></div><div class="detail-tools"><button class="btn btn-outline btn-sm" data-action="share" data-title="${p.title}" data-kind="property">${icon('share')} Compartir</button><button class="btn btn-outline btn-sm" data-action="save" data-id="${p.id}" data-public="${p.publicId}" data-text aria-pressed="${saved}">${saved?'Quitar de guardadas':'Guardar propiedad'}</button></div></header>
  ${gallery(p)}
  <section class="detail-info"><h2>Datos esenciales</h2><dl class="detail-grid">${essentials.map(([k,v])=>h`<div class="detail-item"><dt>${k}</dt><dd>${v}</dd></div>`)}</dl><p class="source-note">Datos revisados por el equipo y publicados el ${fmt.date(p.publishedAt)}. ${occupancyNote(p.occupancy)}.</p></section>
  ${p.appraisalUF?h`<section class="detail-info" id="tasacion" data-appraisal="${p.appraisalUF}"><h2>Tasación</h2><dl class="detail-grid"><div class="detail-item"><dt>Valor de tasación</dt><dd>${money(p.appraisalUF)}</dd></div><div class="detail-item"><dt data-live="current-label">${a?.totalBids?'Oferta vigente':'Precio inicial'}</dt><dd data-live="current">${a?money(a.currentMinor/100):'—'}</dd></div><div class="detail-item"><dt>Bajo tasación</dt><dd><span data-live="discount">${discount(p,a)}%</span></dd></div></dl><p class="source-note">El descuento se calcula sobre la oferta vigente y cambia con cada oferta aceptada. Tasación ilustrativa de demostración: en una publicación real se informa quién la hizo y en qué fecha.</p></section>`:''}
  ${p.mortgage?h`<section class="detail-info" id="credito"><h2>${icon('bank')} Compra con crédito hipotecario</h2><p>Puedes pagar el saldo con un crédito hipotecario. El crédito está sujeto a la aprobación del banco o institución financiera: te recomendamos pedir una preaprobación antes de ofertar y revisar en las bases los plazos para pagar el saldo.</p><p class="source-note">Texto de demostración pendiente de revisión legal. SeSubasta no otorga créditos.</p></section>`:''}
  <section class="detail-info"><h2>Fechas y reglas</h2><dl class="detail-grid"><div class="detail-item"><dt>Inicio · hora de Chile</dt><dd>${fmt.dateTime(a?.start)}</dd></div><div class="detail-item"><dt>Cierre fijo · hora de Chile</dt><dd>${fmt.dateTime(a?.end)}</dd></div><div class="detail-item"><dt>Precio inicial</dt><dd>${a?fmt.uf(a.initialMinor/100):'—'}</dd></div><div class="detail-item"><dt>Incremento mínimo</dt><dd>${a?fmt.uf(a.incrementMinor/100):'—'}</dd></div><div class="detail-item"><dt>Unidad contractual</dt><dd>UF</dd></div><div class="detail-item"><dt>Bases</dt><dd>Versión ${a?.termsVersion||'—'}</dd></div><div class="detail-item"><dt>Garantía de seriedad</dt><dd>${p.conditions?.guaranteeCLP?fmt.clp(p.conditions.guaranteeCLP):'No se exige'}</dd></div></dl><p class="source-note">El cierre es fijo: no hay extensión automática. No se requiere inscripción por propiedad.${p.conditions?.guaranteeCLP?' La garantía se transfiere antes de ofertar y se devuelve si no quedas entre los dos primeros.':''}</p>${result?h`<p><a class="text-link" href="${href(`/remates/${p.slug}/resultado`)}">Ver resultado ${icon('arrow')}</a></p>`:''}</section>
  <section class="detail-info"><h2>Descripción</h2><p>${p.description}</p></section>
  <section class="detail-info">${p.exactLocation?h`<h2>Ubicación</h2><p>${icon('pin')} ${p.address||p.publicLocation}</p>`:h`<h2>Ubicación aproximada</h2><p>${p.lat!=null?h`La dirección exacta no se publica. El mapa muestra la zona de ${p.commune}.`:h`${p.publicLocation}. El mapa no está disponible para esta propiedad.`}</p>`}${p.lat!=null?h`<div id="detailMap" class="detail-map" role="region" aria-label="${p.exactLocation?'Mapa con la ubicación de la propiedad':'Mapa de la zona aproximada'}"><p class="hint">Cargando mapa…</p></div>`:''}</section>
  <section class="detail-info" id="bases"><h2>Documentos públicos autorizados</h2>${p.documents.length?h`<ul class="doc-list">${p.documents.map(d=>h`<li><a href="${FILE_MODE?'#':'/api/v1/documents/'+d.id}" ${FILE_MODE?raw('data-action="file-only"'):raw('target="_blank" rel="noopener"')} data-doc="${d.type}">${icon('file')} <span><strong>${d.name}</strong><small>${d.type} · revisado el ${fmt.date(d.at)}</small></span></a></li>`)}</ul>`:h`<p>Aún no hay documentos públicos para esta propiedad.</p>`}<p class="source-note">Los antecedentes legales internos son privados y no se publican.</p></section>
  <section class="detail-info" id="consultar"><h2>¿Tienes dudas sobre esta propiedad?</h2><p>Déjanos tus datos y el equipo te responderá. No necesitas cuenta para consultar.</p>${leadForm(p)}</section>
  ${related.length?h`<section class="detail-info"><h2>Propiedades relacionadas</h2><div class="property-list compact">${related.map(propertyCard)}</div></section>`:''}</div>
  <aside class="detail-side">${livePanel(p)}<a class="btn btn-outline btn-block" href="#consultar" data-action="scroll" data-target="consultar">Consultar</a><p class="hint">${icon('bell')} Guarda la propiedad para recibir avisos cuando la oportunidad esté por empezar, comience o esté por cerrar.</p></aside></div>
  <div class="sticky-subastar mobile-only" data-live-id="${p.auctionId}"><div><small data-live="current-label">${a?.totalBids?'Oferta vigente':'Precio inicial'}</small><strong data-live="current">${a?money(a.currentMinor/100):'—'}</strong><small data-live="countdown">${Live.countdown(a)}</small></div><a class="btn btn-primary" data-live-cta data-slug="${p.slug}" href="${href(s==='open'?`/remates/${p.slug}/ofertar`:`/remates/${p.slug}`)}">${s==='open'?'Ofertar':'Ver condiciones'}</a></div>`,
  after:()=>{if(p.exactLocation)loadLeaflet().then(()=>{const el=$('#detailMap');if(el){el.innerHTML='';pointMap(el,p,{popup:p.address||p.title})}}).catch(()=>{const el=$('#detailMap');if(el)el.innerHTML='<p class="hint">No se pudo cargar el mapa.</p>'});else mountMap($('#detailMap'),[p],{zoom:12});$$('[data-doc]').forEach(a=>a.addEventListener('click',()=>Analytics.event('document_downloaded',{document_type:a.dataset.doc,property_id:p.publicId})))}}}});
actions.scroll=el=>{const t=document.getElementById(el.dataset.target);if(t){t.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});const f=t.querySelector('input,textarea,select,button');f?.focus({preventScroll:true})}};
actions['file-only']=()=>toast('La descarga de documentos requiere el servidor local.');
function gallery(p){const imgs=p.media.length?p.media:[{url:'assets/propiedades/propiedad-16.webp',alt:'Imagen no disponible'}];return h`<div class="gallery"><button class="gallery-main" data-action="lightbox" data-index="0" aria-label="Ampliar imagen 1 de ${imgs.length}"><img src="${photo(imgs[0])}" alt="${imgs[0].alt}" width="960" height="640"><span class="gallery-count">${icon('grid')} ${imgs.length} ${imgs.length===1?'imagen':'imágenes'} · ilustrativas</span></button>${imgs.length>1?h`<div class="gallery-thumbs">${imgs.slice(1).map((m,i)=>h`<button data-action="lightbox" data-index="${i+1}" aria-label="Ver imagen ${i+2} de ${imgs.length}"><img src="${photo(m)}" alt="${m.alt}" loading="lazy" width="200" height="130"></button>`)}</div>`:''}</div>`}
let lightboxImages=[];
actions.lightbox=el=>{lightboxImages=$$('.gallery img').map(i=>({src:i.src,alt:i.alt}));let i=Number(el.dataset.index);const show=d=>{const im=lightboxImages[i];$('#lbImg',d).src=im.src;$('#lbImg',d).alt=im.alt;$('#lbCap',d).textContent=`${i+1} de ${lightboxImages.length} · ${im.alt}`};
 openDialog({title:'Galería',wide:true,body:h`<figure class="lightbox"><img id="lbImg" alt=""><figcaption id="lbCap"></figcaption></figure><div class="button-row center"><button class="btn btn-outline" id="lbPrev">← Anterior</button><button class="btn btn-outline" id="lbNext">Siguiente →</button></div>`,onOpen:d=>{show(d);const go=k=>{i=(i+k+lightboxImages.length)%lightboxImages.length;show(d)};$('#lbPrev',d).onclick=()=>go(-1);$('#lbNext',d).onclick=()=>go(1);d.addEventListener('keydown',e=>{if(e.key==='ArrowLeft')go(-1);if(e.key==='ArrowRight')go(1)});$('#lbNext',d).focus()}})};
function leadForm(p){return h`<form data-form="lead" class="lead-form" novalidate><input type="hidden" name="auctionId" value="${p.auctionId}"><input type="hidden" name="property" value="${p.publicId+' · '+p.title}"><div class="field-grid"><label class="form-field"><span>Nombre</span><input name="name" autocomplete="name" required></label><label class="form-field"><span>Correo</span><input name="email" type="email" autocomplete="email"></label><label class="form-field"><span>Teléfono (opcional)</span><input name="phone" type="tel" autocomplete="tel" placeholder="+56 9 1234 5678"></label><label class="form-field"><span>Medio preferido</span><select name="preferred"><option>Correo</option><option>Teléfono</option><option>WhatsApp</option></select></label></div><label class="form-field"><span>Objetivo</span><select name="objective"><option>Quiero más información</option><option>Quiero visitar la propiedad</option><option>Tengo dudas sobre las bases</option><option>Otro</option></select></label><label class="form-field"><span>Tu consulta</span><textarea name="message" rows="3"></textarea></label><label class="form-check"><input type="checkbox" name="consent" required> <span>Autorizo que me contacten por esta consulta y acepto la <a href="${href('/privacidad')}" target="_blank">política de privacidad</a>.</span></label><label class="form-check"><input type="checkbox" name="marketing"> <span>Quiero recibir novedades de nuevas oportunidades (opcional).</span></label><input class="hp" name="website" tabindex="-1" autocomplete="off" aria-hidden="true"><button class="btn btn-dark">Enviar consulta</button></form>`}
forms.lead=form=>submitWith(form,async d=>{const r=await POST('/api/v1/remate-leads',{...d,auctionId:Number(d.auctionId),source:currentUrl().pathname,campaign:new URLSearchParams(location.search).get('utm_campaign')||''});clearDraft('lead');Analytics.event('generate_lead',{lead_type:'remate'});form.outerHTML=toHtml(h`<div class="notice success" role="status">${icon('check')} Recibimos tu consulta (código <strong>${r.code}</strong>). Te responderemos por el medio que elegiste.</div>`)});

/* ---------- PUB-06 Sala en vivo y OFR-01 ingreso de oferta ---------- */
async function roomView({params},mode){const {property:p}=await GET('/api/v1/properties/'+encodeURIComponent(params.slug));if(p.auction)Live.accept({auctions:[p.auction]});bidProperty=p;if(Bid.review&&Bid.review.id!==p.auctionId)Bid.reset();await loadGuarantee(p);
 return {title:'Sala de ofertas · '+p.title,html:h`<section class="live-room"><div class="room-header"><a class="back-link" href="${href('/remates/'+p.slug)}">${icon('back')} Volver a la ficha</a><span class="eyebrow">Sala de ofertas</span><h1>${p.title}</h1><p>${p.publicLocation} · ${p.publicId}</p></div>
  <div class="room-layout"><div class="room-info"><img class="room-photo" src="${photo(p.media[0])}" alt="${p.media[0]?.alt||''}" width="800" height="520"><div class="panel"><h2>Cómo funciona esta sala</h2><ul class="check-list"><li>Puedes ofertar las veces que quieras hasta el cierre fijo.</li><li>El servidor calcula el siguiente mínimo y valida cada oferta al instante.</li><li>Si alguien registra una oferta mientras revisas, deberás confirmar con el nuevo mínimo.</li><li>Sin conexión no se envía nada: al reconectar puedes reintentar la misma solicitud.</li>${p.conditions?.guaranteeCLP?h`<li>Esta oportunidad exige una garantía de seriedad de ${fmt.clp(p.conditions.guaranteeCLP)}, confirmada por el equipo antes de ofertar.</li>`:h`<li>Esta oportunidad no exige garantía de seriedad.</li>`}<li>No hay aprobación manual de ofertas.</li></ul><a class="text-link" href="${href('/terminos')}">Leer bases de demostración ${icon('arrow')}</a></div></div>
  <div class="room-side" data-live-id="${p.auctionId}">${livePanel(p,{room:true})}<div class="panel" id="bidFlow">${bidFlowHtml(p)}</div></div></div></section>`,
  after:()=>{if(mode==='ofertar')$('form[data-form="bid"] [name=amount]')?.focus()}}}
route('/remates/:slug/participar',{title:'Sala',focus:true,parent:'/remates',view:x=>roomView(x,'participar')});
route('/remates/:slug/ofertar',{title:'Ofertar',focus:true,parent:'/remates',view:x=>roomView(x,'ofertar')});

/* ---------- RES-01 Resultado ---------- */
route('/remates/:slug/resultado',{title:'Resultado',parent:'/remates',view:async({params})=>{const {property:p,result}=await GET('/api/v1/properties/'+encodeURIComponent(params.slug));const a=p.auction;if(a)Live.accept({auctions:[a]});const s=Live.status(a);let mine=null;if(state.user&&!FILE_MODE){try{mine=await GET('/api/v1/me/results/'+p.auctionId)}catch{}}
 const label={pending_confirmation:'Resultado preliminar · pendiente de confirmación',confirmed:'Adjudicación confirmada',defaulted:'En revisión por incumplimiento',offered_to_runner_up:'Ofrecida al segundo oferente según bases',no_bids:'Sin ofertas · oportunidad desierta'}[result?.status]||(s==='closed'?'Calculando resultado preliminar':'La oportunidad aún no cierra');
 return {title:'Resultado · '+p.title,html:h`<section class="generic narrow" data-live-id="${p.auctionId}"><nav class="breadcrumbs"><a href="${href('/remates')}">Propiedades</a><span aria-hidden="true">›</span><a href="${href('/remates/'+p.slug)}">${p.title}</a><span aria-hidden="true">›</span><span>Resultado</span></nav><h1>Resultado de la oportunidad</h1><p class="lead">${p.title} · ${p.publicLocation}</p>
  <div class="result-card"><span class="status-pill" data-live="status" data-state="${s}">${STATUS_LABEL[s]}</span><h2>${label}</h2><dl class="review-list"><div><dt>Cierre oficial</dt><dd>${fmt.dateTime(a?.end)} (hora de Chile)</dd></div><div><dt>Oferta final registrada</dt><dd data-live="current-uf">${a?fmt.uf(a.currentMinor/100):'—'}</dd></div><div><dt>Participación</dt><dd data-live="people">${Live.people(a)}</dd></div></dl><p class="source-note">“Cerrada” no significa “adjudicada”. La adjudicación requiere confirmación interna según las bases. No se publican identidades de quienes ofertan.</p></div>
  ${state.user?mine?.participated?h`<div class="panel"><h2>Tu resultado</h2><p>${mine.leading?(result?.status==='confirmed'?'Tu oferta fue la más alta y la adjudicación fue confirmada. El equipo te contactará con los próximos pasos.':'Tu oferta fue la más alta al cierre. Es un resultado preliminar: el equipo confirmará la adjudicación según las bases.'):'Tu mejor oferta no fue la más alta al cierre.'}</p><dl class="review-list compact"><div><dt>Tu mejor oferta</dt><dd>${fmt.uf(mine.best.amountMinor/100)}</dd></div><div><dt>Folio</dt><dd>${mine.best.receipt}</dd></div></dl><a class="btn btn-outline" href="${href('/mi-cuenta/ofertas')}">Ver mi historial</a></div>`:h`<p class="notice">No registraste ofertas en esta oportunidad.</p>`:h`<p class="notice">Si participaste, <a href="${href('/ingresar?volver='+encodeURIComponent('/remates/'+p.slug+'/resultado'))}">inicia sesión</a> para ver tu resultado.</p>`}
  <a class="btn btn-dark" href="${href('/remates')}">Explorar otras oportunidades</a></section>`}}});

/* ---------- PUB-04 Cómo funciona ---------- */
/* Cómo funciona: primero se elige el perfil (compradores o vendedores). */
const howHead=(label)=>h`<nav class="breadcrumbs"><a href="${href('/')}">Inicio</a><span aria-hidden="true">›</span><a href="${href('/como-funciona')}">Cómo funciona</a><span aria-hidden="true">›</span><span>${label}</span></nav>`;
route('/como-funciona',{title:'Cómo funciona',view:async()=>({title:'Cómo funciona',html:h`<section class="subpage-head"><nav class="breadcrumbs"><a href="${href('/')}">Inicio</a><span aria-hidden="true">›</span><span>Cómo funciona</span></nav><span class="eyebrow">Oportunidades inmobiliarias</span><h1>¿Cómo funciona?</h1><p>Elige tu perfil para ver el proceso paso a paso.</p></section>
 <section class="section"><div class="how-choice"><a class="how-option" href="${href('/como-funciona/compradores')}">${icon('search')}<strong>Para los compradores</strong><span>Cómo revisar una propiedad, ofertar y qué pasa al cierre.</span>${icon('arrow')}</a><a class="how-option" href="${href('/como-funciona/vendedores')}">${icon('home')}<strong>Para los vendedores</strong><span>Cómo presentar tu propiedad y qué pasa después.</span>${icon('arrow')}</a></div></section>`})});
/* Paso a paso para compradores y vendedores (nov. 2026): diagrama con pasos alternados, ilustración en círculo y reglas en cada paso.
   Montos y plazos entregados por Dirección. Paso: [ícono principal, ícono de apoyo, título, texto, reglas, enlaces]. */
const BUYER_STEPS=[
 ['user','check','Crea tu cuenta en SeSubasta','Regístrate con tus datos y confirma tu correo. Con tu cuenta puedes guardar propiedades, recibir alertas y participar.',['Es gratis.','Una sola cuenta para todas las oportunidades.'],[['/registro','Crear cuenta']]],
 ['search','home','Elige la propiedad y revisa la ficha','Antes de ofertar, revisa la tasación, los documentos, las bases, las fechas y si la propiedad admite crédito hipotecario.',['Las propiedades parten entre un 30 % y un 35 % bajo el valor de tasación.','Si tienes dudas, usa el botón Consultar: el equipo responde por escrito.'],[['/remates','Ver todas las propiedades']]],
 ['bank','lock','Paga la garantía de seriedad','Para ofertar en una propiedad debes pagar su garantía de seriedad de $1.000.000. Transfiere a la cuenta de SeSubasta con el código que te entregamos.',['La garantía es por propiedad: si quieres ofertar en dos, pagas dos garantías.','Si no te adjudicas, se devuelve.'],[['/blog/garantia-de-seriedad-para-que-sirve-y-cuando-se-devuelve','¿Qué es la garantía de seriedad?']]],
 ['clock','shield','Espera la validación (24 horas)','El equipo revisa tu transferencia y valida la garantía. Solo con la garantía validada puedes ofertar.',['La validación demora hasta 24 horas: paga con anticipación.','Te avisamos por correo cuando esté lista.'],[]],
 ['arrow','spark','Oferta hasta el cierre','Cada oferta debe superar la oferta vigente en el incremento definido en las bases. Puedes volver a ofertar las veces que quieras.',['La primera oferta parte desde el precio inicial.','Igualar una oferta no la supera: no se aceptan ofertas iguales.','El cierre es fijo, sin extensión automática.','Cada oferta queda registrada con hora oficial y folio.'],[]],
 ['file','clock','Si ganas, paga en 48 horas','Al cierre se publica el resultado preliminar. Si tu oferta es la más alta, tienes 48 horas para pagar los gastos operacionales.',['Tu garantía de seriedad abona una parte del monto.','Si no pagas en el plazo, puedes perder la garantía según las bases.'],[]],
 ['check','users','Cierra el acuerdo y se te adjudica','Con el pago cumplido, el equipo comercial te contacta, cierran el acuerdo y se te adjudica la propiedad.',['El equipo te acompaña en los pasos finales de la compra.'],[['/preguntas-frecuentes','Preguntas frecuentes']]]];
const SELLER_STEPS=[
 ['file','check','Completa el formulario','Cuéntanos el tipo de propiedad, su ubicación, sus características, tu situación de venta y cómo contactarte.',['Es privado: tu propiedad no se publica todavía.','No pedimos documentos en esta etapa.'],[['/ingresar-inmueble/formulario','Comenzar formulario']]],
 ['bell','doc','Recibe tu código','Te llega un correo con el código de tu solicitud y un resumen de lo que enviaste.',['Con el código puedes hacer seguimiento.'],[]],
 ['users','user','El equipo te contacta','Una persona responsable revisa tu solicitud y conversa contigo sobre la propiedad, tus plazos y el precio inicial.',['Un precio inicial atractivo atrae más ofertas.'],[]],
 ['shield','file','Revisión legal y ficha','Nuestro abogado revisa los antecedentes y preparamos la ficha con fotografías, tasación y condiciones.',['Solo se publica con los antecedentes revisados.'],[]],
 ['eye','calendar','Publicación','Revisas la ficha y, con la aprobación final, se publica con su fecha de inicio y de cierre.',['Las personas interesadas pagan su garantía antes de ofertar.'],[]],
 ['check','users','Recibe ofertas y cierra','Al cierre, el equipo te acompaña en los pasos finales con quien hizo la mejor oferta.',['No prometemos precio ni plazo: el precio lo define la competencia.'],[['/contacto','Conversar con el equipo']]]];
const howFlow=steps=>h`<ol class="how-flow">${steps.map(([ic,sub,t,d,rules,links],i)=>h`<li class="how-step"><div class="step-art" data-tone="${i%3}" aria-hidden="true"><div class="art-screen"><span class="art-ico">${icon(ic)}</span><span class="art-bar"></span><span class="art-bar short"></span><span class="art-btn"></span></div><span class="art-badge">${icon(sub)}</span></div>
 <div class="step-text"><h2><span class="step-num">${i+1}</span>${t}</h2><p>${d}</p><ul>${rules.map(r=>h`<li>${icon('check')}<span>${r}</span></li>`)}</ul>${links.length?h`<div class="step-links">${links.map(([u,l])=>h`<a class="btn btn-outline btn-sm" href="${href(u)}">${l}</a>`)}</div>`:''}</div></li>`)}</ol>`;
route('/como-funciona/compradores',{title:'Cómo funciona para compradores',parent:'/como-funciona',view:async()=>({title:'Cómo funciona para compradores',html:h`<section class="how-hero">${howHead('Para los compradores')}<h1>Compra tu próxima propiedad en 7 pasos</h1><p>Desde crear tu cuenta hasta que se te adjudica la propiedad. Las reglas están en cada paso.</p></section>
 <section class="section">${howFlow(BUYER_STEPS)}
 <div class="cta-banner compact"><img src="assets/propiedades/propiedad-07.webp" alt="" loading="lazy" width="1200" height="600"><div class="cta-banner-content"><span class="eyebrow on-dark">¿Listo para empezar?</span><h2>Revisa las propiedades disponibles</h2><p>Elige una propiedad, paga su garantía y prepárate para ofertar.</p><div class="cta-actions"><a class="btn btn-primary" href="${href('/remates')}">Ver todas las propiedades ${icon('arrow')}</a><a class="btn btn-ghost-light" href="${href('/preguntas-frecuentes')}">Preguntas frecuentes</a></div></div></div></section>`})});

/* ---------- Quiénes somos: por qué SeSubasta, enfoque (carrusel), equipo, valores y llamado a ver remates ---------- */
const FOCUS=[['building','Oportunidades inmobiliarias','Nos dedicamos solo a propiedades. Conocemos sus documentos, plazos y particularidades.'],
 ['eye','Ventas transparentes','Tasación, ofertas y reglas visibles para todas las personas. El precio lo define la competencia.'],
 ['shield','Respaldo legal','Cada ficha pasa por la revisión de nuestro abogado antes de publicarse.'],
 ['file','Educación del comprador','Explicamos cada paso para que participes con información y sin depender de intermediarios.']];
const TEAM=[['Fundador de SeSubasta','Felipe Rojas','Creó SeSubasta para acercar las oportunidades inmobiliarias a más personas y lidera su visión.'],
 ['Abogado','Miguel Díaz','Revisa los antecedentes legales de cada propiedad y resguarda que las bases se cumplan.'],
 ['Jefa de Operaciones','Jessica Valenzuela','Coordina las oportunidades, valida las garantías y acompaña a compradores y vendedores.'],
 ['Líder de Marketing','Erika Orrego','Comunica cómo funciona SeSubasta con información simple y útil.']];
const VALUES=[['eye','Transparencia','Mostramos tasación, documentos, ofertas y reglas antes de que decidas. Sin letra chica.'],['users','Accesibilidad','Te educamos sobre este mercado y facilitamos tu participación con una garantía de seriedad accesible y crédito hipotecario.'],['file','Educación','Explicamos cada etapa con guías, noticias y respuestas claras.'],['shield','Seguridad','Cada oferta queda registrada con hora oficial y cada ficha pasa por revisión legal.'],['check','Igualdad de condiciones','Las mismas reglas, los mismos datos y el mismo cierre para quienes participan.'],['spark','Expertos inmobiliarios','Conocemos el proceso de principio a fin y te acompañamos en cada etapa.']];
route('/quienes-somos',{title:'Quiénes somos',view:async()=>({title:'Quiénes somos',html:h`<section class="about-hero" aria-labelledby="whyTitle">
  <div class="about-hero-top"><div class="about-hero-text"><span class="eyebrow on-dark">Por qué SeSubasta</span><h1 id="whyTitle">Propiedades <em>sin barreras</em></h1><p>Comprar una propiedad siempre implica una inversión importante. Por eso facilitamos el acceso de dos formas: te educamos sobre cómo funciona este mercado y te damos facilidades para participar, como una garantía de seriedad accesible y propiedades que admiten crédito hipotecario.</p></div>
  <div class="about-hero-media"><img src="assets/propiedades/propiedad-04.webp" alt="" width="640" height="420"></div></div>
  <div class="pillars"><article class="pillar"><span class="pillar-n">01</span><h2>Te educamos sobre este mercado</h2><p>Explicamos cómo funciona cada oportunidad, qué revisar y qué preguntar, para que decidas con información y sin depender de intermediarios.</p><ul><li>${icon('check')}Fichas con tasación, documentos y condiciones visibles.</li><li>${icon('check')}<span>Guías y noticias en nuestro <a href="${href('/blog')}">blog</a>.</span></li><li>${icon('check')}Un equipo que responde tus consultas por escrito.</li></ul></article>
  <article class="pillar"><span class="pillar-n">02</span><h2>Te damos facilidades para participar</h2><p>Para ofertar constituyes una garantía de seriedad por cada propiedad. Es accesible en comparación con el mercado y, si no te adjudicas, se devuelve.</p><ul><li>${icon('check')}Garantía de seriedad accesible en comparación con el mercado.</li><li>${icon('check')}Propiedades entre un 30 % y un 35 % bajo el valor de tasación.</li><li>${icon('check')}Propiedades que admiten crédito hipotecario.</li></ul></article></div></section>
 <section class="section catalog-teaser" aria-labelledby="specTitle"><div class="section-head"><div><span class="eyebrow">Nuestra especialidad</span><h2 id="specTitle">Nuestro enfoque</h2><p>Lo que nos distingue en cada oportunidad.</p></div></div>
  <div class="carousel"><button type="button" class="carousel-btn prev" data-action="carousel" data-dir="-1" aria-label="Anteriores">${icon('back')}</button><div class="carousel-track" role="list" aria-labelledby="specTitle">${FOCUS.map(([ic,t,d],i)=>h`<div class="carousel-item" role="listitem"><article class="focus-card" data-tone="${i}"><span class="focus-ico">${icon(ic)}</span><span class="focus-n">0${i+1}</span><h3>${t}</h3><p>${d}</p></article></div>`)}</div><button type="button" class="carousel-btn next" data-action="carousel" data-dir="1" aria-label="Siguientes">${icon('chevron')}</button></div></section>
 <section class="section" aria-labelledby="teamTitle"><div class="section-head"><div><span class="eyebrow">Nuestro equipo</span><h2 id="teamTitle">Las personas detrás de cada oportunidad</h2><p>Cuatro personas trabajan juntas para que cada oportunidad sea clara y segura.</p></div></div>
  <ul class="team-grid">${TEAM.map(([role,name,d])=>h`<li class="team-card"><div class="team-photo" role="img" aria-label="Fotografía de ${name} (pendiente)">${icon('user')}</div><span class="team-area">${role}</span><strong>${name}</strong><p>${d}</p></li>`)}</ul></section>
 <section class="section" aria-labelledby="valTitle"><div class="section-head"><div><span class="eyebrow">Nuestros valores</span><h2 id="valTitle">Lo que nos guía</h2></div></div>
  <ul class="values-bento">${VALUES.map(([ic,t,d],i)=>h`<li data-tone="${i}"><span class="val-ico">${icon(ic)}</span><span class="val-n">0${i+1}</span><strong>${t}</strong><p>${d}</p></li>`)}</ul></section>
 <section class="section"><div class="cta-banner"><img src="assets/propiedades/propiedad-18.webp" alt="" loading="lazy" width="1200" height="600"><div class="cta-banner-content"><span class="eyebrow on-dark">Oportunidades inmobiliarias</span><h2>Tu próxima propiedad te está esperando</h2><p>Revisa las oportunidades abiertas y próximas, compara la tasación y participa con información clara.</p><div class="cta-actions"><a class="btn btn-primary" href="${href('/remates')}">Ver todas las propiedades ${icon('arrow')}</a><a class="btn btn-ghost-light" href="${href('/remates?status=scheduled')}">Próximas oportunidades</a></div></div></div></section>`})});

route('/como-funciona/vendedores',{title:'Cómo funciona para vendedores',parent:'/como-funciona',view:async()=>({title:'Cómo funciona para vendedores',html:h`<section class="how-hero">${howHead('Para los vendedores')}<h1>Vende tu propiedad en 6 pasos</h1><p>Presenta tu propiedad para evaluación. La solicitud es privada: no se publica ni se promete precio, plazo o resultado.</p></section>
 <section class="section">${howFlow(SELLER_STEPS)}
 <div class="cta-banner compact"><img src="assets/propiedades/propiedad-09.webp" alt="" loading="lazy" width="1200" height="600"><div class="cta-banner-content"><span class="eyebrow on-dark">Vende con nosotros</span><h2>Presenta tu propiedad</h2><p>Completa un formulario breve y el equipo te contactará.</p><div class="cta-actions"><a class="btn btn-primary" href="${href('/ingresar-inmueble/formulario')}">Comenzar formulario ${icon('arrow')}</a><a class="btn btn-ghost-light" href="${href('/contacto')}">Contacto</a></div></div></div></section>`})});

const sellSteps=()=>h`<section class="section two-col"><div><h2>Qué te pediremos</h2><ul class="check-list"><li>Tipo de propiedad, región, comuna y dirección.</li><li>Características básicas: dormitorios, baños y superficie.</li><li>Situación de venta y, si quieres, un precio esperado.</li><li>Tus datos de contacto y horario preferido.</li></ul><p>No pedimos RUT, documentos de identidad ni títulos en esta etapa.</p></div><div><h2>Qué pasa después</h2><ol class="steps"><li><span class="step-n">1</span><strong>Recibes un código</strong><p>Te llega por correo junto con un resumen de tu solicitud.</p></li><li><span class="step-n">2</span><strong>El equipo te contacta</strong><p>Una persona responsable revisa tu solicitud y te escribe.</p></li><li><span class="step-n">3</span><strong>Evaluación y antecedentes</strong><p>Si avanza, preparamos la ficha y el equipo Legal revisa los antecedentes antes de cualquier publicación.</p></li></ol></div></section>`;
/* ---------- PUB-05 Ingresar inmueble, SEL-01 formulario por pasos y SEL-02 confirmación ---------- */
route('/ingresar-inmueble',{title:'Ingresa tu inmueble',view:async()=>({title:'Ingresa tu inmueble',html:h`<section class="subpage-head"><nav class="breadcrumbs"><a href="${href('/')}">Inicio</a><span aria-hidden="true">›</span><span>Ingresa tu inmueble</span></nav><span class="eyebrow">Vender con SeSubasta</span><h1>Presenta tu propiedad para evaluación</h1><p>Completa un formulario breve. Tu solicitud es privada: no se publica ni se promete precio, plazo o resultado.</p><a class="btn btn-primary" href="${href('/ingresar-inmueble/formulario')}">Comenzar formulario</a></section>
${sellSteps()}
 <section class="section"><p class="notice">${icon('lock')} Tus datos se usan solo para evaluar la propiedad y contactarte. Revisa la <a href="${href('/privacidad')}">política de privacidad</a>. ¿Prefieres conversar? Escríbenos desde <a href="${href('/contacto')}">Contacto</a>.</p></section>`})});
const SELL_STEPS=['Tipo y ubicación','Características','Situación de venta','Contacto','Imágenes y antecedentes','Revisa y envía'];
let sellStep=session.get('ss-sell-step',0);
route('/ingresar-inmueble/formulario',{title:'Formulario de ingreso',focus:true,parent:'/ingresar-inmueble',view:async()=>{const facets=(await GET('/api/v1/properties?limit=1').catch(()=>({facets:{regions:[],communes:{}}}))).facets;const regions=['Región Metropolitana','Región de Valparaíso','Región de La Araucanía','Región del Biobío','Región de O’Higgins','Región de Los Lagos','Región de Coquimbo','Región de Antofagasta','Región del Maule','Otra región'];const C=window.__COMMUNES||{};
 const communesFor=r=>Object.entries(C).filter(([,v])=>v.region===r).map(([k])=>k).sort((a,b)=>a.localeCompare(b,'es'));
 return {title:'Ingresa tu inmueble',html:h`<section class="generic narrow"><a class="back-link" href="${href('/ingresar-inmueble')}">${icon('back')} Volver</a><h1>Ingresa tu inmueble</h1><p>Guardamos un borrador en este navegador mientras completas el formulario.</p>
 <ol class="progress" aria-label="Progreso">${SELL_STEPS.map((s,i)=>h`<li class="${i<sellStep?'done':i===sellStep?'current':''}" ${i===sellStep?raw('aria-current="step"'):''}><span>${i+1}</span><small>${s}</small></li>`)}</ol>
 <form data-form="sell" class="sell-form" novalidate>
  <fieldset data-step="0" ${sellStep!==0?raw('hidden'):''}><legend>1. Tipo y ubicación</legend><label class="form-field"><span>Tipo de propiedad *</span><select name="type" required><option value="">Selecciona</option>${['Casa','Departamento','Terreno','Oficina','Local comercial','Bodega','Otro'].map(t=>h`<option>${t}</option>`)}</select></label><label class="form-field"><span>Región *</span><select name="region" required data-sell-region><option value="">Selecciona</option>${regions.map(r=>h`<option>${r}</option>`)}</select></label><label class="form-field"><span>Comuna *</span><select name="commune" required data-sell-commune><option value="">Selecciona primero la región</option></select><small class="hint">Si tu comuna no aparece, elige “Otra comuna” e indícala en la descripción.</small></label><label class="form-field"><span>Dirección</span><input name="address" autocomplete="street-address"><small class="hint">Es privada: solo la ve el equipo.</small></label></fieldset>
  <fieldset data-step="1" ${sellStep!==1?raw('hidden'):''}><legend>2. Características</legend><div class="field-grid"><label class="form-field"><span>Dormitorios</span><input name="rooms" type="number" min="0" inputmode="numeric"></label><label class="form-field"><span>Baños</span><input name="baths" type="number" min="0" inputmode="numeric"></label><label class="form-field"><span>Superficie (m²)</span><input name="area" type="number" min="1" inputmode="decimal"></label></div><label class="form-field"><span>Descripción</span><textarea name="description" rows="4" placeholder="Estado, orientación, ampliaciones u otros datos útiles"></textarea></label></fieldset>
  <fieldset data-step="2" ${sellStep!==2?raw('hidden'):''}><legend>3. Situación de venta</legend><label class="form-field"><span>Situación *</span><select name="saleSituation" required><option value="">Selecciona</option><option>Quiero vender pronto</option><option>Estoy evaluando opciones</option><option>Propiedad heredada o en sucesión</option><option>Otra situación</option></select></label><div class="field-grid"><label class="form-field"><span>Precio esperado (opcional)</span><input name="expectedPrice" type="number" min="0" inputmode="numeric"></label><label class="form-field"><span>Unidad</span><select name="expectedUnit"><option>UF</option><option>CLP</option></select></label></div><p class="hint">El precio esperado es referencial y no compromete una valorización.</p></fieldset>
  <fieldset data-step="3" ${sellStep!==3?raw('hidden'):''}><legend>4. Cómo podemos contactarte</legend><label class="form-field"><span>Nombre y apellido *</span><input name="name" autocomplete="name" required></label><div class="field-grid"><label class="form-field"><span>Correo *</span><input name="email" type="email" autocomplete="email" required></label><label class="form-field"><span>Teléfono</span><input name="phone" type="tel" autocomplete="tel" placeholder="+56 9 1234 5678"></label></div><div class="field-grid"><label class="form-field"><span>Horario de contacto</span><select name="contactHours"><option>Mañana</option><option>Tarde</option><option>Cualquier horario</option></select></label><label class="form-field"><span>Medio preferido</span><select name="preferred"><option>Correo</option><option>Teléfono</option><option>WhatsApp</option></select></label></div></fieldset>
  <fieldset data-step="4" ${sellStep!==4?raw('hidden'):''}><legend>5. Imágenes y antecedentes</legend><p class="notice">${icon('lock')} En esta etapa no solicitamos fotografías ni documentos. Si la evaluación avanza, el equipo te pedirá los antecedentes por un canal seguro y con un aviso de privacidad específico.</p></fieldset>
  <fieldset data-step="5" ${sellStep!==5?raw('hidden'):''}><legend>6. Revisa y envía</legend><div id="sellSummary" class="review-list"></div><label class="form-check"><input type="checkbox" name="consent" required> <span>Autorizo que me contacten por esta solicitud y acepto el aviso de <a href="${href('/privacidad')}" target="_blank">privacidad</a>. *</span></label><label class="form-check"><input type="checkbox" name="marketing"> <span>Quiero recibir novedades (opcional).</span></label><input class="hp" name="website" tabindex="-1" autocomplete="off" aria-hidden="true"></fieldset>
  <div class="step-buttons">${sellStep>0?h`<button type="button" class="btn btn-outline" data-action="sell-step" data-dir="-1">Anterior</button>`:''}${sellStep<5?h`<button type="button" class="btn btn-dark" data-action="sell-step" data-dir="1">Continuar</button>`:h`<button type="submit" class="btn btn-primary">Enviar solicitud</button>`}</div><p class="hint">* Campos obligatorios.</p></form></section>`,
 after:root=>{const f=$('form[data-form="sell"]',root);const fill=()=>{const r=f.region.value;const list=communesFor(r);const cur=drafts.get(draftKey(f.commune))||f.commune.value;f.commune.innerHTML=toHtml(h`<option value="">${r?'Selecciona':'Selecciona primero la región'}</option>${list.map(c=>h`<option ${c===cur?'selected':''}>${c}</option>`)}${r?h`<option ${cur==='Otra comuna'?'selected':''}>Otra comuna</option>`:''}`)};fill();f.region.addEventListener('change',fill);if(sellStep===5)sellSummary(f)}}}});
function sellSummary(f){const d=formData(f);const rows=[['Tipo',d.type],['Ubicación',[d.commune,d.region].filter(Boolean).join(', ')],['Dirección',d.address||'No indicada'],['Características',[d.rooms&&d.rooms+' dorm.',d.baths&&d.baths+' baños',d.area&&d.area+' m²'].filter(Boolean).join(' · ')||'No indicadas'],['Situación',d.saleSituation],['Precio esperado',d.expectedPrice?`${fmt.num(d.expectedPrice)} ${d.expectedUnit}`:'No indicado'],['Contacto',[d.name,d.email,d.phone].filter(Boolean).join(' · ')]];$('#sellSummary').innerHTML=toHtml(rows.map(([k,v])=>h`<div><dt>${k}</dt><dd>${v}</dd></div>`))}
const SELL_REQUIRED=[['type','region','commune'],[],['saleSituation'],['name','email'],[],['consent']];
actions['sell-step']=el=>{const f=$('form[data-form="sell"]');const dir=Number(el.dataset.dir);if(dir>0){const fields={};for(const n of SELL_REQUIRED[sellStep]){const x=f.elements[n];if(x.type==='checkbox'?!x.checked:!x.value.trim())fields[n]='Este campo es obligatorio.'}if(sellStep===3&&f.email.value&&!/^\S+@\S+\.\S+$/.test(f.email.value))fields.email='Ingresa un correo válido.';if(sellStep===1&&f.area.value&&Number(f.area.value)<=0)fields.area='La superficie debe ser mayor que cero.';if(Object.keys(fields).length)return showErrors(f,{message:'Completa los campos obligatorios.',fields});if(sellStep===0)Analytics.event('seller_form_started',{property_type:f.type.value})}
 sellStep=Math.max(0,Math.min(5,sellStep+dir));session.set('ss-sell-step',sellStep);render({keepScroll:false})};
forms.sell=form=>submitWith(form,async d=>{let r;try{r=await POST('/api/v1/seller-leads',{...d,communeFree:d.commune==='Otra comuna',source:'/ingresar-inmueble/formulario'})}catch(e){const first=Object.keys(e.fields||{})[0];const fs=first&&form.elements[first]?.closest('fieldset[data-step]');if(fs&&Number(fs.dataset.step)!==sellStep){sellStep=Number(fs.dataset.step);session.set('ss-sell-step',sellStep);await render({keepScroll:false});const f2=$('form[data-form="sell"]');if(f2)showErrors(f2,e);return}throw e}clearDraft('sell');sellStep=0;session.del('ss-sell-step');Analytics.event('seller_form_submitted',{property_type:d.type,region:d.region});navigate('/ingresar-inmueble/confirmacion/'+r.code,{replace:true})});
route('/ingresar-inmueble/confirmacion/:code',{title:'Solicitud recibida',view:async({params})=>({title:'Solicitud recibida',html:h`<section class="system-state success"><span class="system-icon">${icon('check')}</span><h1>Recibimos tu solicitud</h1><p>Código de seguimiento: <strong class="code">${params.code}</strong></p><p>Te enviamos una copia por correo. Una persona del equipo revisará la información y te contactará. Tu propiedad no se publica automáticamente.</p><div class="button-row center"><a class="btn btn-dark" href="${href('/')}">Volver al inicio</a><a class="btn btn-outline" href="${href('/remates')}">Ver todas las propiedades</a></div></section>`})});

/* ---------- PUB-07 Blog y PUB-08 Artículo ---------- */
const postCard=p=>h`<article class="post-card"><a href="${href('/blog/'+p.slug)}"><img src="${p.cover.url}" alt="${p.cover.alt}" loading="lazy" width="480" height="300"></a><div><span class="blog-tag">${p.category?.name||'Blog'}</span><h3><a href="${href('/blog/'+p.slug)}">${p.title}</a></h3><p>${p.excerpt}</p><small>${p.author} · ${fmt.date(p.publishedAt)}${p.updatedAt>p.publishedAt+86400000?h` · actualizado ${fmt.date(p.updatedAt)}`:''} · ${p.readMinutes} min de lectura</small></div></article>`;
/* Carrusel de artículos (mismo control que el de propiedades). */
const postCarousel=(items,labelId)=>h`<div class="carousel posts"><button type="button" class="carousel-btn prev" data-action="carousel" data-dir="-1" aria-label="Anteriores">${icon('back')}</button><div class="carousel-track" role="list" aria-labelledby="${labelId}">${items.map(p=>h`<div class="carousel-item" role="listitem">${postCard(p)}</div>`)}</div><button type="button" class="carousel-btn next" data-action="carousel" data-dir="1" aria-label="Siguientes">${icon('chevron')}</button></div>`;
/* Índice lateral: marca la sección que se está leyendo. */
document.addEventListener('scroll',()=>{const links=$$('[data-toc]');if(!links.length)return;let cur=links[0].dataset.toc;for(const l of links){const el=document.getElementById(l.dataset.toc);if(el&&el.getBoundingClientRect().top<140)cur=l.dataset.toc}links.forEach(l=>l.toggleAttribute('aria-current',l.dataset.toc===cur))},{passive:true});
/* Blog: 3 banners deslizantes, noticias recientes y, al final, el buscador por categoría con todas las noticias.
   Con categoría o búsqueda activa se muestra directo el buscador con los resultados. */
async function blogView({params,query}){const cat=params.cat||'';const n=Math.min(Number(query.n)||9,60);const q=query.q||'';const filtered=!!(cat||q);
 const [data,top]=await Promise.all([GET(`/api/v1/blog/posts?limit=${n}${cat?'&category='+encodeURIComponent(cat):''}${q?'&q='+encodeURIComponent(q):''}`),filtered?null:GET('/api/v1/blog/posts?limit=9')]);
 const c=data.categories.find(x=>x.slug===cat);if(cat&&!c)throw new ApiError(404,{});
 const slides=top?top.items.slice(0,3):[],recent=top?top.items.slice(3,9):[];
 const bar=h`<form class="blog-search" data-form="blogsearch" role="search" data-nodraft><label class="form-field"><span>Categoría</span><select name="cat" data-nodraft><option value="">Todas las categorías</option>${data.categories.filter(x=>x.count).map(x=>h`<option value="${x.slug}" ${c?.slug===x.slug?raw('selected'):''}>${x.name} (${x.count})</option>`)}</select></label><label class="form-field grow"><span>Buscar</span><input name="q" type="search" value="${q}" placeholder="Palabra clave, por ejemplo: crédito" data-nodraft></label><button class="btn btn-dark">${icon('search')}<span>Buscar</span></button></form>`;
 const all=h`<section class="section" id="todas" aria-labelledby="allTitle"><div class="section-head"><div><span class="eyebrow">${filtered?'Resultados':'Todas las noticias'}</span><h2 id="allTitle">${q?'Resultados de búsqueda':c?'Artículos de la categoría':'Explora por categoría'}</h2>${filtered?h`<p>${data.total===1?'1 artículo':data.total+' artículos'}${q?h` para “${q}”`:''}${c?h` en ${c.name}`:''}. <a href="${href('/blog')}">Limpiar filtros</a></p>`:h`<p>Elige una categoría o busca un tema.</p>`}</div></div>${bar}
  ${data.items.length?h`<div class="post-grid">${data.items.map(postCard)}</div>${data.total>data.items.length?h`<div class="load-more"><a class="btn btn-outline" href="${href((c?'/blog/categoria/'+c.slug:'/blog')+'?'+(q?'q='+encodeURIComponent(q)+'&':'')+'n='+(n+9))}" data-replace>Cargar más artículos</a><small>Mostrando ${data.items.length} de ${data.total}</small></div>`:''}`:h`<div class="empty-state"><h2>No encontramos artículos ${c?'en esta categoría':''}${q?' para esa búsqueda':''}</h2><a class="btn btn-dark" href="${href('/blog')}">Ver todos los artículos</a></div>`}</section>`;
 const head=h`<section class="subpage-head"><nav class="breadcrumbs"><a href="${href('/')}">Inicio</a><span aria-hidden="true">›</span>${c?h`<a href="${href('/blog')}">Blog</a><span aria-hidden="true">›</span><span>${c.name}</span>`:h`<span>Blog</span>`}</nav><span class="eyebrow">Blog de SeSubasta</span><h1>${c?c.name:'Noticias y guías para comprar y vender'}</h1><p>${c?c.description:'Explicaciones claras sobre oportunidades, propiedades, documentos y ofertas.'}</p></section>`;
 if(filtered)return {title:c?c.name+' · Blog':'Blog',html:h`${head}${all}`};
 return {title:'Blog',html:h`${head}
 ${slides.length?h`<section class="section blog-slider-wrap" aria-roledescription="carrusel" aria-label="Artículos destacados"><div class="blog-slider" data-slider><div class="blog-slides">${slides.map((p,i)=>h`<a class="blog-slide" href="${href('/blog/'+p.slug)}" aria-roledescription="diapositiva" aria-label="${i+1} de ${slides.length}"><img src="${p.cover.url}" alt="${p.cover.alt}" ${i?raw('loading="lazy"'):''}><div class="blog-slide-content"><span class="blog-tag">${p.category?.name||'Blog'}</span><h2>${p.title}</h2><p>${p.excerpt}</p><span class="btn btn-primary btn-sm">Leer artículo ${icon('arrow')}</span></div></a>`)}</div>
  <div class="slider-dots">${slides.map((p,i)=>h`<button type="button" data-action="slide" data-to="${i}" aria-label="Ir al artículo ${i+1}" aria-current="${i===0}"></button>`)}</div></div></section>`:''}
 ${recent.length?h`<section class="section" aria-labelledby="recentTitle"><div class="section-head"><div><span class="eyebrow">Noticias recientes</span><h2 id="recentTitle">Lo último del blog</h2></div></div>${postCarousel(recent,'recentTitle')}</section>`:''}
 ${all}`}}
forms.blogsearch=form=>{const cat=form.cat?.value||'',q=form.q.value.trim();navigate((cat?'/blog/categoria/'+cat:'/blog')+(q?'?q='+encodeURIComponent(q):''))};
/* Banners del blog: avanzan solos cada 6 s (salvo con el puntero encima, foco dentro o movimiento reducido). */
const slideTo=(slider,i)=>{const t=slider.querySelector('.blog-slides');const n=t.children.length;i=(i+n)%n;t.scrollTo({left:i*t.clientWidth,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})};
const slideIndex=slider=>{const t=slider.querySelector('.blog-slides');return Math.round(t.scrollLeft/Math.max(1,t.clientWidth))};
actions.slide=el=>{const s=el.closest('[data-slider]');slideTo(s,el.dataset.to!=null?Number(el.dataset.to):slideIndex(s)+Number(el.dataset.dir))};
document.addEventListener('scroll',e=>{const t=e.target;if(!(t instanceof Element)||!t.classList.contains('blog-slides'))return;const s=t.closest('[data-slider]');const i=slideIndex(s);s.querySelectorAll('.slider-dots button').forEach((b,k)=>b.setAttribute('aria-current',String(k===i)))},true);
setInterval(()=>{const s=document.querySelector('[data-slider]');if(!s||document.hidden||s.matches(':hover,:focus-within')||matchMedia('(prefers-reduced-motion: reduce)').matches)return;slideTo(s,slideIndex(s)+1)},6000);
route('/blog',{title:'Blog',view:blogView});
route('/blog/categoria/:cat',{title:'Blog',parent:'/blog',view:blogView});
route('/blog/:slug',{title:'Artículo',parent:'/blog',view:async({params})=>{const r=await GET('/api/v1/blog/posts/'+encodeURIComponent(params.slug));if(r.redirect)return {redirect:'/blog/'+r.redirect};const p=r.post;const toc=headings(p.body);Analytics.event('blog_article_viewed',{article_slug:p.slug,category:p.category?.slug||''});
 return {title:p.title,html:h`<article class="article"><header class="article-head"><nav class="breadcrumbs"><a href="${href('/')}">Inicio</a><span aria-hidden="true">›</span><a href="${href('/blog')}">Blog</a>${p.category?h`<span aria-hidden="true">›</span><a href="${href('/blog/categoria/'+p.category.slug)}">${p.category.name}</a>`:''}</nav><span class="blog-tag">${p.category?.name||'Blog'}</span><h1>${p.title}</h1><p class="lead">${p.excerpt}</p><p class="article-meta">${p.author} · Publicado el ${fmt.date(p.publishedAt)}${p.updatedAt>p.publishedAt+86400000?h` · Actualizado el ${fmt.date(p.updatedAt)}`:''} · ${p.readMinutes} min de lectura</p></header>
  <img class="article-cover" src="${p.cover.url}" alt="${p.cover.alt}" width="1200" height="600">
  <div class="article-layout">${toc.length>=2?h`<aside class="toc" aria-label="Índice del artículo"><strong>Índice</strong><ol>${toc.map(t=>h`<li><a href="#${t.id}" data-action="scroll" data-target="${t.id}" data-toc="${t.id}">${t.text}</a></li>`)}</ol></aside>`:''}<div class="article-body"><div class="prose">${md(p.body)}</div>
  <div class="button-row"><button class="btn btn-outline" data-action="share" data-title="${p.title}" data-kind="article">${icon('share')} Compartir</button></div>
  <p class="source-note">Contenido informativo general. No reemplaza la revisión profesional que requiera cada caso.</p></div></div></article>
  ${r.related.length?h`<section class="section" aria-labelledby="relTitle"><div class="section-head"><div><span class="eyebrow">Sigue leyendo</span><h2 id="relTitle">Artículos relacionados</h2></div></div>${postCarousel(r.related,'relTitle')}</section>`:''}`}}});

/* ---------- Ayuda (HELP-01 a HELP-03) y páginas legales ---------- */
route('/preguntas-frecuentes',{title:'Preguntas frecuentes',view:async()=>({title:'Preguntas frecuentes',html:h`<section class="generic narrow"><nav class="breadcrumbs"><a href="${href('/')}">Inicio</a><span aria-hidden="true">›</span><span>Preguntas frecuentes</span></nav><h1>Preguntas frecuentes</h1>${faqList(state.config.faqs)}<p>¿No encuentras tu respuesta? <a href="${href('/contacto')}">Escríbenos</a>.</p></section>`})});
route('/contacto',{title:'Contacto',view:async({query})=>{const c=state.config.contact;const buyNow=query?.tema==='compra-inmediata';const ref=String(query?.propiedad||'').replace(/[^A-Za-z0-9-]/g,'').slice(0,20);return {title:'Contacto',html:h`<section class="generic narrow"><nav class="breadcrumbs"><a href="${href('/')}">Inicio</a><span aria-hidden="true">›</span><span>Contacto</span></nav><h1>Contacta a SeSubasta</h1><p>Respondemos ${c.hours?c.hours.toLowerCase():'en horario hábil'}. También puedes escribir a <a href="mailto:${c.email}">${c.email}</a> o seguirnos en Instagram ${c.instagram}.</p>
 <form data-form="contact" class="panel" novalidate><div class="field-grid"><label class="form-field"><span>Nombre *</span><input name="name" autocomplete="name" required></label><label class="form-field"><span>Correo *</span><input name="email" type="email" autocomplete="email" required></label></div><div class="field-grid"><label class="form-field"><span>Teléfono</span><input name="phone" type="tel" autocomplete="tel"></label><label class="form-field"><span>Tema</span><select name="topic"><option ${buyNow?raw('selected'):''}>Compra inmediata</option><option ${buyNow?'':raw('selected')}>Duda sobre una oportunidad</option><option>Mi cuenta</option><option>Vender una propiedad</option><option>Privacidad o eliminación de datos</option><option>Otro</option></select></label></div><label class="form-field"><span>Mensaje *</span><textarea name="message" rows="5" required minlength="10">${buyNow?`Me interesa la compra inmediata de la propiedad ${ref||''}.`:''}</textarea></label><label class="form-check"><input type="checkbox" name="consent" required> <span>Acepto que usen mis datos para responder esta consulta (<a href="${href('/privacidad')}" target="_blank">privacidad</a>). *</span></label><input class="hp" name="website" tabindex="-1" autocomplete="off" aria-hidden="true"><button class="btn btn-dark">Enviar mensaje</button></form></section>`}}});
forms.contact=form=>submitWith(form,async d=>{const r=await POST('/api/v1/contact',{...d,source:'/contacto'});clearDraft('contact');Analytics.event('generate_lead',{lead_type:'contact'});form.outerHTML=toHtml(h`<div class="system-state success compact" role="status"><span class="system-icon">${icon('check')}</span><h2>Consulta recibida</h2><p>Tu código es <strong>${r.code}</strong>. Te enviamos una copia por correo.</p></div>`)});
const LEGAL_ROUTES={'/privacidad':'privacidad','/terminos':'terminos','/cookies':'cookies','/eliminacion-de-datos':'eliminacion'};
for(const [path,key] of Object.entries(LEGAL_ROUTES))route(path,{title:'Legal',view:async()=>{const l=await GET('/api/v1/legal/'+key);return {title:l.title,html:h`<section class="generic narrow legal"><nav class="breadcrumbs"><a href="${href('/')}">Inicio</a><span aria-hidden="true">›</span><span>${l.title}</span></nav><h1>${l.title}</h1><p class="source-note">Versión ${l.version}</p><div class="prose">${md(l.body)}</div>${key==='cookies'?h`<button class="btn btn-dark" data-action="cookie-settings">Configurar mis preferencias</button>`:''}${key==='eliminacion'?h`<div class="button-row"><a class="btn btn-dark" href="${href('/mi-cuenta/perfil')}">Ir a Perfil y privacidad</a><a class="btn btn-outline" href="${href('/contacto')}">No puedo ingresar a mi cuenta</a></div>`:''}</section>`}}});

/* ---------- herramientas locales: bandeja de correos de prueba y mapa de pantallas ---------- */
const MAIL_CAT={auction:'Mis oportunidades',saved:'Guardadas',new:'Nuevas propiedades',news:'Blog',account:'Cuenta',staff:'Equipo'};let devMails=[];
route('/dev/correos',{title:'Correos de prueba',server:true,back:false,view:async({query})=>{const {items,provider}=await GET('/api/v1/dev/mail');devMails=items;const to=query.para||'';const rows=items.filter(m=>!to||m.to.toLowerCase().includes(to.toLowerCase()));return {title:'Correos de prueba',html:h`<section class="generic"><h1>Correos de prueba</h1><p>Solo existe en el servidor local. Aquí llega cada correo que envía el sitio: verificación, recuperación, códigos de acceso, comprobantes, alertas y avisos del equipo. ${provider!=='local'?'El envío real está activo ('+(provider==='brevo'?'Brevo':'Resend')+'): además de verse aquí, llegan a cada bandeja de entrada.':'Sin proveedor de correo configurado, los correos solo se ven aquí y no llegan a las bandejas.'} <button class="link-btn" data-action="reload">Actualizar</button></p>
 <form class="toolbar" data-form="mailfilter" data-nodraft><label class="form-field"><span>Filtrar por destinatario</span><input name="para" value="${to}" placeholder="alex@comprador.demo.cl"></label><button class="btn btn-dark">Filtrar</button></form>
 ${rows.length?h`<ul class="mail-list">${rows.map(m=>h`<li><div><strong>${m.subject}</strong><small>Para ${m.to} · ${fmt.rel(m.at)} · ${MAIL_CAT[m.category]||'Cuenta'} · ${{queued:'en cola',local:'entregado localmente',sent:'enviado',failed:'falló'}[m.status]||m.status}</small></div><p>${m.body}</p><div class="button-row">${m.link?h`<a class="btn btn-dark btn-sm" href="${m.link.replace(/^https?:\/\/[^/]+/,'')}">Abrir enlace</a>`:''}${m.html?h`<button class="btn btn-outline btn-sm" data-action="mail-preview" data-id="${m.id}">Ver correo con diseño</button>`:''}${m.unsubscribeUrl?h`<a class="btn btn-outline btn-sm" href="${m.unsubscribeUrl.replace(/^https?:\/\/[^/]+/,'')}">Probar “dejar de recibir”</a>`:''}</div></li>`)}</ul>`:h`<div class="empty-state">Aún no hay correos.</div>`}</section>`}}});
forms.mailfilter=form=>navigate('/dev/correos'+(form.para.value.trim()?'?para='+encodeURIComponent(form.para.value.trim()):''));
actions['mail-preview']=el=>{const m=devMails.find(x=>x.id===el.dataset.id);if(!m)return;openDialog({title:m.subject,wide:true,body:h`<p class="hint">Para ${m.to}</p><iframe class="mail-frame" sandbox="" title="Vista previa del correo" srcdoc="${m.html}"></iframe>`})};
